  css += "\n.jobs-reference>.filters{align-items:center;gap:18px}.visibility-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;flex:1;min-width:410px;max-width:660px;order:2}.visibility-card{display:flex;align-items:center;gap:10px;border:1px solid #aebfd5;border-radius:10px;padding:12px;background:#f8fbff;min-width:0}.visibility-card>svg{width:24px;height:24px;color:#1268d4}.visibility-card h3{font-size:10px;font-weight:700;line-height:1.4;margin:0;color:#16365e}.visibility-card p{font-size:11px;margin:4px 0;color:#496681}.visibility-card p strong{font-size:20px;font-weight:750;color:#1268d4;margin-right:3px}.visibility-card small{display:block;font-size:9px;color:#637a98;line-height:1.4}.visibility-card small b{color:#16365e}@media(max-width:1100px){.visibility-cards{max-width:none;width:100%;flex-basis:100%}}@media(max-width:650px){.visibility-cards{min-width:0;gap:6px}.visibility-card{padding:10px 8px;gap:6px;align-items:flex-start;flex-direction:column}.visibility-card h3{font-size:9px}.visibility-card>svg{width:20px;height:20px}.visibility-card small{font-size:9px}}\n";
  function navButton(key,label,ico) {return '<button class="nav '+(view===key?'active':'')+'" data-action="nav" data-view="'+key+'">'+icon(ico)+esc(label)+'</button>';}
  function shell(content,e) {return '<style>'+css+'</style><div class="layout"><aside class="sidebar" aria-label="Navegação do recrutador"><div class="sidebar-label">PORTAL DO RECRUTADOR</div>'+navButton('overview','Visão geral','home')+navButton('jobs','Minhas vagas','briefcase')+navButton('candidates','Candidaturas','users')+navButton('profile','Perfil da empresa','company')+navButton('plans','Planos e pagamentos','card')+navButton('verification','Verificação','shield')+navButton('settings','Configurações','settings')+'<div class="support">'+navButton('support','Ajuda e suporte','support')+navButton('exit','Sair','exit')+'</div></aside><main class="main">'+content+'</main></div>';}
  function intro(title,subtitle,button) {return '<div class="intro"><div><h1>'+esc(title)+'</h1><p>'+esc(subtitle)+'</p></div>'+(button||'')+'</div>';}
  function publish() {return '<button class="primary" data-action="publish">'+icon('plus')+'Publicar vaga</button>';}
  function planStrip(e,vs) {var p=plan(e),used=vs.length,ratio=Math.min(100,100*used/p.limit);return '<section class="card plan" aria-label="Seu plano"><span class="icon">'+icon('crown')+'</span><div><div class="plan-title">'+esc(p.name)+'<span class="badge '+(p.active?'active':'closed')+'">'+(p.active?'Ativo':'Expirado')+'</span></div><small>'+used+' de '+p.limit+' publicações utilizadas</small></div><div class="plan-progress" role="progressbar" aria-label="Publicações utilizadas" aria-valuemin="0" aria-valuemax="'+p.limit+'" aria-valuenow="'+used+'"><span style="width:'+ratio+'%"></span></div><span class="plan-date">'+(p.until?'Válido até '+dateBR(p.until):'Plano gratuito')+'</span><button class="secondary" data-action="nav" data-view="plans">Gerenciar plano '+icon('arrow')+'</button></section>';}
  function table(vs,cs,full) {if(!vs.length)return '<div class="empty">Nenhuma vaga encontrada.</div>';return '<div class="table-wrap"><table class="'+(full?'jobs-table':'')+'"><thead><tr><th>Vaga</th><th>Status</th><th>Candidaturas</th><th>Ações</th></tr></thead><tbody>'+vs.map(function(v){var id=esc(v.id),uf=String(v.uf||v.estado||v.siglaEstado||'').trim(),n=count(v,cs);return '<tr><td data-label="Vaga"><strong>'+esc(v.cargo||v.titulo||'Vaga')+'</strong><small>'+esc(v.cidade||'Cidade não informada')+(uf?' • '+esc(uf.toUpperCase()):'')+'</small></td><td data-label="Status">'+badge(jobStatus(v))+'</td><td data-label="Candidaturas"><button class="candidate-count" data-action="manage" data-id="'+id+'">'+n+' '+(n===1?'candidato':'candidatos')+'</button></td><td data-label="Ações"><div class="row-actions job-actions"><button class="primary manage-job" data-action="job-settings" data-id="'+id+'">'+(full?'Gerenciar vaga':'Gerenciar')+'</button>'+'</div></td></tr>';}).join('')+'</tbody></table></div>';}
  function candidateList(cs,vs,limit) {if(!cs.length)return '<div class="empty">Nenhuma candidatura recebida ainda.<br>As novas candidaturas aparecerão aqui.</div>';var sorted=cs.slice().sort(function(a,b){return (date(b)||0)-(date(a)||0);});return sorted.slice(0,limit == null ? 3 : limit).map(function(c){var name=candidateName(c),initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(function(w){return w[0];}).join(''),jid=String(c.vagaId||c.vaga_id||c.idVaga),v=vs.find(function(x){return String(x.id)===jid;})||{},d=date(c);return '<article class="candidate"><span class="avatar">'+esc(initials)+'</span><div class="candidate-body"><strong>'+esc(name)+'</strong><p>'+esc(v.cargo||v.titulo||'Candidatura')+'</p><span class="location">'+icon('pin')+esc(c.cidade||c.localidade||'Localidade não informada')+'</span></div><div class="candidate-action"><small>'+(d?d.toLocaleDateString('pt-BR'):'Data não informada')+'</small><button class="secondary" data-action="manage" data-id="'+esc(jid)+'">Ver candidatura</button></div></article>';}).join('');}
  function performance(vs,cs) {var since=new Date();since.setHours(0,0,0,0);since.setDate(since.getDate()-29);var daily=Array(30).fill(0);cs.forEach(function(c){var d=date(c);if(d){var i=Math.floor((d-since)/86400000);if(i>=0&&i<30)daily[i]++;}});var max=Math.max.apply(null,daily.concat([1])),points=daily.map(function(n,i){return (i*600/29).toFixed(1)+','+(150-130*n/max).toFixed(1);}).join(' ');var advanced=cs.filter(function(c){return /entrevista|selecionad|aprovad|contratad/.test(norm(c.status));}).length;var durations=cs.filter(function(c){return norm(c.status)==='contratado';}).map(function(c){var a=date(c),b=new Date(c.contratadoEm||c.dataContratacao||'');return a&&!isNaN(b)&&b>=a?(b-a)/86400000:null;}).filter(function(x){return x!==null;});var avg=durations.length?Math.round(durations.reduce(function(a,b){return a+b;},0)/durations.length):null;var views=vs.reduce(function(n,v){return n+(Number(v.visualizacoes||v.views||v.visualizacoesTotal)||0);},0);return '<section class="card performance"><div class="heading"><div><h2>Desempenho do recrutamento</h2><p>Candidaturas recebidas nos últimos 30 dias</p></div><button class="refresh" data-action="refresh">Atualizar dados</button></div><div class="performance-layout"><div><div class="chart" role="img" aria-label="Candidaturas por dia nos últimos 30 dias: '+daily.reduce(function(a,b){return a+b;},0)+' no período"><svg viewBox="0 0 600 170" preserveAspectRatio="none"><defs><linearGradient id="em-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#72b9ff" stop-opacity=".35"/><stop offset="100%" stop-color="#72b9ff" stop-opacity=".02"/></linearGradient></defs><path d="M0 20H600M0 65H600M0 110H600M0 150H600" stroke="#e1ebf7" stroke-width="1" stroke-dasharray="4 4"/><polygon points="0,150 '+points+' 600,150" fill="url(#em-area)"/><polyline points="'+points+'" fill="none" stroke="#0876ed" stroke-width="2.5"/></svg></div><div class="chart-labels"><span>'+since.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})+'</span><span>Últimos 30 dias</span><span>'+new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})+'</span></div></div><div class="performance-stats"><div class="perf-stat"><span class="icon">'+icon('eye')+'</span><div><small>Visualizações acumuladas</small><strong>'+views.toLocaleString('pt-BR')+'</strong></div></div><div class="perf-stat"><span class="icon">'+icon('chart')+'</span><div><small>Taxa de avanço</small><strong>'+(cs.length?Math.round(100*advanced/cs.length)+'%':'—')+'</strong></div></div><div class="perf-stat"><span class="icon">'+icon('clock')+'</span><div><small>Tempo médio de contratação</small><strong>'+(avg===null?'—':avg+' dias')+'</strong></div></div></div></div></section>';}

  function companyHero(e){
    var api=window.emLinkEmpresa,list=api?api.catalogo():[];
    e=list.find(function(x){return String(x.cnpj)===String(e.cnpj);})||e;
    var name=e.nome_fantasia||e.nomeFantasia||e.nome||'Sua empresa',p=plan(e);
    var logo=e.logo?'<img src="'+esc(e.logo)+'" alt="Logo de '+esc(name)+'">':'<span>'+esc(name.charAt(0).toUpperCase())+'</span>';
    var available=api&&api.elegivel(e)&&e.linkEmpresaSlug,link=available?api.url(e):'';
    return '<section class="company-hero"><div class="company-hero-top"><div class="company-identity"><div class="company-logo">'+logo+'</div><div><span class="company-eyebrow">ÁREA DA EMPRESA</span><div class="company-title"><h1>'+esc(name)+'</h1><span class="company-plan">'+esc(p.name)+(p.active?'':' • Vigência encerrada')+'</span></div><p>Gerencie suas vagas e candidaturas em um só lugar.</p></div></div>'+publish()+'</div><div class="company-address"><div class="company-url">'+icon('pin')+(available?'<strong>'+esc(e.linkEmpresaSlug+'.'+api.dominioPrevisto)+'</strong><small>Domínio em preparação</small>':'<strong>Uma página exclusiva para sua empresa</strong><small>Disponível com plano pago ativo</small>')+'</div><div class="company-link-actions">'+(available?'<a class="hero-link" href="'+esc(link)+'">Ver página '+icon('arrow')+'</a><button class="hero-copy" data-action="copy-company-link" data-url="'+esc(link)+'">'+icon('card')+' Copiar link de teste</button>':'<button class="hero-copy" data-action="all-plans">Conhecer planos '+icon('arrow')+'</button>')+'</div></div></section>';
  }
  css += ".company-hero{margin-bottom:22px;padding:20px 22px 16px;border:1px solid #d7e6f7;border-radius:12px;background:#fff;color:#16365e;box-shadow:0 3px 12px #16365e05}.company-hero-top{display:flex;justify-content:space-between;align-items:center;gap:20px}.company-identity{display:flex;align-items:center;gap:14px;min-width:0}.company-logo{display:grid;place-items:center;flex:0 0 52px;width:52px;height:52px;overflow:hidden;border:1px solid #d7e6f7;border-radius:9px;background:#fff;color:#096cdf;font-size:25px;font-weight:700}.company-logo img{width:100%;height:100%;object-fit:contain;padding:5px}.company-eyebrow{display:block;color:#7185a1;font-size:9px;font-weight:700;letter-spacing:.9px;margin-bottom:5px}.company-title{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.company-hero h1{color:#16365e;font-size:23px;line-height:1.25;letter-spacing:-.4px;overflow-wrap:anywhere}.company-hero p{color:#7285a1;font-size:12px;line-height:1.5;margin-top:5px}.company-plan{display:inline-flex;padding:5px 9px;background:#edf5ff;border-radius:20px;font-size:10px;color:#096cdf;white-space:nowrap}.company-hero .primary{background:#096cdf;color:#fff;padding:11px 16px;border-radius:8px;font-size:12px}.company-hero .primary:hover{background:#075bbd}.company-address{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:16px;padding-top:13px;border-top:1px solid #e7eef7}.company-url{display:flex;align-items:center;gap:9px;flex-wrap:wrap;min-width:0}.company-url>svg{width:18px;height:18px;color:#096cdf}.company-address strong{font-size:13px;color:#096cdf;overflow-wrap:anywhere;min-width:0}.company-address small{padding:5px 8px;background:#f2f6fb;border-radius:20px;color:#7285a1;font-size:9px;white-space:nowrap}.company-link-actions{display:flex;gap:8px;flex-wrap:wrap;flex-shrink:0}.hero-link,.hero-copy{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:9px 11px;border:1px solid #c6ddf6;border-radius:7px;font-size:11px;font-weight:600;text-decoration:none;color:#096cdf;background:#fff}.hero-copy{background:#edf5ff;border-color:#edf5ff}.hero-link:hover,.hero-copy:hover{background:#e5f0ff}.hero-link svg,.hero-copy svg{width:14px;height:14px}@media(max-width:1100px){.company-address{align-items:flex-start;flex-direction:column;gap:10px}}@media(max-width:650px){.company-hero{padding:16px;border-radius:10px}.company-hero-top{align-items:flex-start;flex-direction:column;gap:13px}.company-identity{align-items:flex-start;gap:10px}.company-logo{width:44px;height:44px;flex-basis:44px}.company-hero h1{font-size:18px}.company-title{gap:7px}.company-hero p{font-size:11px}.company-hero-top>.primary{width:100%}.company-address{margin-top:13px;padding-top:12px}.company-address strong{font-size:12px}.company-link-actions{width:100%}.hero-link,.hero-copy{flex:1}}";
  function overview(e,vs,cs) {var name=e.nome_fantasia||e.nomeFantasia||e.nome||sessionStorage.getItem('empresaNome')||'Sua empresa';var active=vs.filter(function(v){return jobStatus(v)==='active';}).length,pending=vs.filter(function(v){return jobStatus(v)==='pending';}).length,interviews=cs.filter(function(c){return norm(c.status).indexOf('entrevista')>=0;}).length;var metrics=[['Vagas ativas',active,'briefcase','','Vagas publicadas e recebendo candidaturas','jobs','active'],['Em análise',pending,'clock','orange','Publicações aguardando aprovação','jobs','pending'],['Candidaturas',cs.length,'users','','Total de candidaturas recebidas','candidates','all'],['Entrevistas',interviews,'calendar','purple','Candidatos em fase de entrevista','interviews','all']];return companyHero(e)+'<div class="kpis">'+metrics.map(function(m){return '<button class="card kpi" data-action="nav" data-view="'+m[5]+'" data-filter="'+m[6]+'"><span class="icon '+m[3]+'">'+icon(m[2])+'</span><div><h2>'+m[0]+'</h2><strong>'+m[1]+'</strong><small>'+m[4]+'</small></div></button>';}).join('')+'</div>'+planStrip(e,vs)+'<div class="columns"><section class="card section"><div class="heading"><h2>Minhas vagas</h2><button class="link" data-action="nav" data-view="jobs">Ver todas '+icon('arrow')+'</button></div>'+table(vs.slice(0,3),cs,false)+'</section><section class="card section"><div class="heading"><h2>Novas candidaturas</h2><button class="link" data-action="nav" data-view="candidates">Ver todas '+icon('arrow')+'</button></div>'+candidateList(cs,vs)+'</section></div>'+performance(vs,cs);}
  function jobLocation(v){return String(v.cidade||'').trim()+(v.uf||v.estado||v.siglaEstado?' • '+String(v.uf||v.estado||v.siglaEstado).trim().toUpperCase():'');}
  function jobFilterFields(vs){
   function select(id,label,values,current){return '<label>'+label+'<select id="'+id+'" aria-label="'+label+'"><option value="">Todas</option>'+values.map(function(x){return '<option value="'+esc(x)+'" '+(current===x?'selected':'')+'>'+esc(x)+'</option>';}).join('')+'</select></label>';}
   var cities=Array.from(new Set(vs.map(jobLocation).filter(Boolean))).sort(function(a,b){return a.localeCompare(b,'pt-BR');});
   var areas=Array.from(new Set(vs.map(function(v){return String(v.area||'').trim();}).filter(Boolean))).sort(function(a,b){return a.localeCompare(b,'pt-BR');});
   return '<div class="job-extra-filters">'+select('job-location','Localidade',cities,locationFilter)+select('job-area','Área',areas,areaFilter)+'<button class="secondary" data-action="clear-job-filters">Limpar filtros</button></div>';
  }

  function visibilityCards(vs){
    var p=plan(company()),caps={trimestral:[10,5,2],semestral:[20,7,4],anual:[40,10,8]},limits=p.active?(caps[p.key]||[0,0,0]):[0,0,0];
    var now=new Date(),rows=[['destaque','Vagas em destaque','star',limits[0]],['urgente','Vagas urgentes','bolt',limits[1]],['confidencial','Vagas confidenciais','lock',limits[2]]];
    return '<div class="visibility-cards" aria-label="Recursos do plano">'+rows.map(function(r){
      function marked(v){return r[0]==='urgente'?yes(v.contratacaoUrgente||v.urgente):yes(v[r[0]]);}
      var active=vs.filter(function(v){return jobStatus(v)==='active'&&marked(v)&&(r[0]!=='urgente'||!v.urgenteAte||new Date(v.urgenteAte).getTime()>Date.now());}).length;
      var used=vs.filter(function(v){if(!marked(v))return false;if(r[0]!=='confidencial')return jobStatus(v)!=='closed';var d=new Date(v.confidencialAtivadaEm||v.dataPublicacao||v.criadoEm||'');return isNaN(d.getTime())||d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();}).length;
      return '<article class="visibility-card">'+modalIcon(r[2])+'<div><h3>'+r[1]+'</h3><p><strong>'+active+'</strong> ativa'+(active===1?'':'s')+'</p><small><b>'+Math.max(0,r[3]-used)+'</b> disponíve'+(Math.max(0,r[3]-used)===1?'l':'is')+(r[0]==='confidencial'?' neste mês':' no plano')+'</small></div></article>';
    }).join('')+'</div>';
  }

  function jobsView(vs,cs) {var filtered=vs.filter(function(v){return (statusFilter==='all'||jobStatus(v)===statusFilter)&&(!locationFilter||jobLocation(v)===locationFilter)&&(!areaFilter||String(v.area||'').trim()===areaFilter)&&norm((v.cargo||v.titulo||'')+' '+(v.cidade||'')).indexOf(norm(query))>=0;});var size=8,total=Math.max(1,Math.ceil(filtered.length/size));pageNumber=Math.min(pageNumber,total);return '<section class="card section jobs-reference">'+intro('Minhas vagas','Acompanhe suas vagas e gerencie os candidatos.',publish())+'<div class="filters"><div class="job-tabs" aria-label="Filtrar por status">'+[['all','Todas'],['active','Ativas'],['pending','Em análise'],['paused','Pausadas'],['closed','Encerradas']].map(function(x){return '<button class="'+(statusFilter===x[0]?'selected':'')+'" data-action="job-filter" data-filter="'+x[0]+'" aria-pressed="'+(statusFilter===x[0])+'">'+x[1]+'</button>';}).join('')+'</div>'+visibilityCards(vs)+'</div>'+jobFilterFields(vs)+'<div id="job-results">'+table(filtered.slice((pageNumber-1)*size,pageNumber*size),cs,true)+'<div class="pager"><span>'+filtered.length+' vagas • Página '+pageNumber+' de '+total+'</span><div class="row-actions"><button class="secondary" data-action="prev" '+(pageNumber<=1?'disabled':'')+'>Anterior</button><button class="secondary" data-action="next" '+(pageNumber>=total?'disabled':'')+'>Próxima</button></div></div></div></section>';}
  function plansView(e,vs) {var p=plan(e);return intro('Seu plano e recursos','Consulte a capacidade e a vigência da assinatura da sua empresa.','<button class="secondary" data-action="nav" data-view="overview">Voltar ao painel</button>')+'<section class="card plan-full">'+planStrip(e,vs)+'<h2>Recursos do seu plano</h2><div class="features">'+p.features.map(function(f){return '<div class="feature">'+icon('check')+esc(f)+'</div>';}).join('')+'</div><p class="note">A verificação da empresa depende da análise do cadastro. Consulte as condições dos planos para mais detalhes.</p><button class="secondary" data-action="all-plans" style="margin-top:20px">Conhecer outros planos</button></section>';}
  function interviewsView(vs,cs){var list=cs.filter(function(c){return norm(c.status).indexOf('entrevista')>=0;});return intro('Entrevistas','Candidatos em fase de entrevista nas vagas da sua empresa.','<button class="secondary" data-action="nav" data-view="overview">Voltar ao painel</button>')+'<section class="card section">'+(list.length?candidateList(list,vs,list.length):'<div class="empty">Nenhum candidato em fase de entrevista.</div>')+'</section>';}
  function navigate(v,filter) {if(v==='candidates'){invoke('irPara',['candidatos-empresa']);return;}var routes={profile:'perfil-empresa',verification:'verificacao-empresa',settings:'perfil-empresa',support:'contato'};if(routes[v]){invoke('irPara',[routes[v]]);return;}if(v==='exit'){if(typeof window.sairEmpresa==='function')window.sairEmpresa();else if(typeof window.logoutEmpresa==='function')window.logoutEmpresa();else{['empregaMaisPapel','empresaNome','empresaCnpj','empresaEmail','empregaMaisSupabaseAccessToken','empregaMaisSupabaseRefreshToken','empregaMaisEmpresaRemotaV49'].forEach(function(k){sessionStorage.removeItem(k);});invoke('irPara',['login-empresa']);}return;}view=v;query='';statusFilter=filter||'all';pageNumber=1;render();window.scrollTo({top:0,behavior:'smooth'});}
  function manage(id) {sessionStorage.setItem('vagaCandidatosSelecionada',String(id));if(typeof window.abrirGestaoVagaEmpregaMais==='function')window.abrirGestaoVagaEmpregaMais(id);else if(typeof window.abrirCandidatosDaVaga==='function')window.abrirCandidatosDaVaga(id);else{invoke('irPara',['candidatos-empresa']);var url=new URL(location.href);url.searchParams.set('vaga',id);history.replaceState(null,'',url.toString());if(typeof window.renderizarCandidatosEmpresa==='function')window.renderizarCandidatosEmpresa();}}

  function yes(v){return v===true||v===1||['true','1','sim'].indexOf(norm(v))>=0;}
  function deadline(v){var raw=v.expiraEm;if(!raw)return NaN;return new Date(/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw+'T23:59:59':raw).getTime();}
  function remaining(v,now){if(norm(v.status)==='pausada')return Math.max(0,Number(v.prazoRestanteMs)||0);var end=deadline(v);if(!isFinite(end)){var start=new Date(v.dataPublicacao||v.criadoEm).getTime();end=start+Number(v.planoDias||30)*86400000;}return Math.max(0,end-now);}
  function lifecycle(v,op,now){
    var next=Object.assign({},v),status=jobStatus(v);
    if(status==='closed')throw Error('Uma vaga encerrada não pode ser reaberta ou alterada.');
    if(op==='pause'){if(status!=='active')throw Error('Somente vagas ativas podem ser pausadas.');var left=remaining(v,now);if(!left)throw Error('O prazo desta vaga já terminou.');next.status='pausada';next.prazoRestanteMs=left;next.pausadaEm=new Date(now).toISOString();next.statusAntesPausa=v.status;}
    if(op==='resume'){if(status!=='paused')throw Error('Esta vaga não está pausada.');var rest=remaining(v,now);if(!rest)throw Error('Esta vaga não possui prazo restante.');next.status=next.statusAntesPausa||'ativa';next.expiraEm=new Date(now+rest).toISOString();next.retomadaEm=new Date(now).toISOString();next.pausadaEm='';next.prazoRestanteMs=null;}
    if(op==='close'){next.status='encerrada';next.dataEncerramento=new Date(now).toISOString();next.prazoRestanteMs=0;}
    return next;
  }
  function modalIcon(type){var paths={edit:'M16 3l5 5-12 12-6 1 1-6Z M14 5l5 5',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z',bolt:'m13 2-8 12h7l-1 8 8-12h-7Z',lock:'M7 10V7a5 5 0 0 1 10 0v3 M5 10h14v11H5Z',pause:'M9 5v14M15 5v14',play:'m8 4 12 8-12 8Z',close:'M6 6l12 12M18 6 6 18'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[type]+'"/></svg>';}
  function closeSettings(){var d=root&&root.getElementById('job-settings-dialog');if(d){d.close();d.remove();}modalJobId=null;modalOp='';if(modalReturn&&modalReturn.isConnected)modalReturn.focus();}
  function openSettings(id,button){
    var v=jobs().find(function(x){return String(x.id)===String(id);});if(!v)return;
    closeSettings();modalJobId=String(id);modalReturn=button;var st=jobStatus(v),closed=st==='closed';
    function toggle(key,title,sub,type,value){return '<label class="settings-toggle">'+modalIcon(type)+'<span><strong>'+title+'</strong><small>'+sub+'</small></span><input type="checkbox" role="switch" id="setting-'+key+'" '+(yes(value)?'checked':'')+' '+(closed?'disabled':'')+'><i aria-hidden="true"></i></label>';}
    function field(key,title,multi){return '<label>'+title+(multi?'<textarea':'<input')+' id="setting-'+key+'" '+(multi?'rows="3"':'type="text" value="'+esc(v[key]||'')+'"')+' '+(closed?'disabled':'')+'>'+(multi?esc(v[key]||'')+'</textarea>':'')+'</label>';}
    var d=document.createElement('dialog');d.id='job-settings-dialog';d.className='settings-dialog';
    d.innerHTML='<div class="settings-head"><span class="settings-symbol">'+icon('briefcase')+'</span><div><h2 id="settings-title">Gerenciar vaga</h2><strong>'+esc(v.cargo||v.titulo||'Vaga')+'</strong><small>'+icon('pin')+esc(jobLocation(v))+'</small></div>'+badge(st)+'<button class="settings-x" data-action="settings-cancel" aria-label="Fechar">'+modalIcon('close')+'</button></div><div class="settings-body"><div class="settings-feature">'+modalIcon('edit')+'<div><strong>Editar informações da vaga</strong><small>Cargo, localidade, salário e descrição</small></div><button class="secondary" data-action="settings-edit" '+(closed?'disabled':'')+'>Editar vaga</button></div><div id="settings-fields" class="settings-fields" hidden>'+field('cargo','Cargo')+field('cidade','Cidade')+field('uf','UF')+field('salario','Salário')+field('descricao','Descrição',true)+field('requisitos','Requisitos',true)+field('beneficios','Benefícios',true)+'<button class="link" data-action="settings-full-edit">Abrir formulário completo</button></div><h3>Visibilidade da vaga</h3>'+toggle('destaque','Vaga em destaque','Mais visibilidade na lista de vagas','star',v.destaque)+toggle('urgente','Vaga urgente','Sinalize a prioridade da contratação','bolt',v.contratacaoUrgente||v.urgente)+toggle('confidencial','Vaga confidencial','Oculte o nome da empresa na publicação','lock',v.confidencial)+
    (closed?'<div class="settings-feature"><div><strong>Vaga encerrada</strong><small>O encerramento é definitivo. Esta vaga não pode ser reaberta.</small></div></div>':st==='active'||st==='paused'?'<div class="settings-feature">'+modalIcon(st==='paused'?'play':'pause')+'<div><strong>'+(st==='paused'?'Retomar vaga':'Pausar vaga')+'</strong><small>'+(st==='paused'?'Continue pelo prazo restante: '+Math.ceil(remaining(v,Date.now())/86400000)+' dia(s).':'Interrompa a publicação sem consumir o prazo restante.')+'</small></div><button class="secondary" data-action="settings-lifecycle" data-op="'+(st==='paused'?'resume':'pause')+'">'+(st==='paused'?'Retomar vaga':'Pausar vaga')+'</button></div><button class="settings-end" data-action="settings-lifecycle" data-op="close">Encerrar vaga definitivamente</button>':'')+'<p class="settings-feedback" id="settings-feedback" role="status"></p></div><footer class="settings-footer"><button class="secondary" data-action="settings-cancel">Cancelar</button><button class="primary" data-action="settings-save" '+(closed?'disabled':'')+'>Salvar alterações</button></footer>';
    d.setAttribute('aria-labelledby','settings-title');root.appendChild(d);d.addEventListener('cancel',function(ev){ev.preventDefault();closeSettings();});d.addEventListener('click',function(ev){if(ev.target===d)closeSettings();});d.showModal();
  }
  function saveSettings(){
    var d=root.getElementById('job-settings-dialog'),id=modalJobId;
    try{
      if(!jobs().some(function(v){return String(v.id)===id;}))throw Error('Esta vaga não pertence à empresa atual.');
      var vs=invoke('carregarVagasPortal')||[],i=vs.findIndex(function(v){return String(v.id)===id;});if(i<0)throw Error('Vaga não encontrada.');
      var v=vs[i],next=lifecycle(v,modalOp,Date.now()),p=plan(company()),caps={trimestral:[10,5],semestral:[20,7],anual:[40,10]},cap=caps[p.key]||[0,0];
      var dest=d.querySelector('#setting-destaque').checked,urg=d.querySelector('#setting-urgente').checked,conf=d.querySelector('#setting-confidencial').checked;
      var own=jobs().filter(function(x){return String(x.id)!==id&&jobStatus(x)!=='closed';});
      if(dest&&!yes(v.destaque)&&(!p.active||own.filter(function(x){return yes(x.destaque);}).length>=cap[0]))throw Error('O limite de vagas em destaque do plano foi atingido.');
      if(urg&&!yes(v.contratacaoUrgente||v.urgente)&&(!p.active||own.filter(function(x){return yes(x.contratacaoUrgente||x.urgente);}).length>=cap[1]))throw Error('O limite de vagas urgentes do plano foi atingido.');
      if(conf&&!yes(v.confidencial)&&(!p.active||!caps[p.key]))throw Error('Vaga confidencial está disponível nos planos Trimestral, Semestral e Anual.');
      var edited=false;if(!d.querySelector('#settings-fields').hidden){['cargo','cidade','uf','salario','descricao','requisitos','beneficios'].forEach(function(k){next[k]=d.querySelector('#setting-'+k).value.trim();});if(!next.cargo||!next.cidade||!next.descricao)throw Error('Preencha cargo, cidade e descrição.');if(next.uf&&!/^[A-Za-z]{2}$/.test(next.uf))throw Error('Informe a sigla do estado com duas letras.');next.uf=next.uf.toUpperCase();next.salarioNumero=invoke('extrairSalarioNumero',[next.salario])||0;edited=['cargo','cidade','uf','salario','descricao','requisitos','beneficios'].some(function(k){return String(next[k]||'')!==String(v[k]||'');});if(edited){var approved=invoke('vagaJaFoiAprovada',[v])||norm(v.aprovacao)==='aprovada';var edits=Number(invoke('edicoesAposAprovacao',[v])||v.edicoesAposAprovacao||0);if(approved&&edits>=1)throw Error('Esta vaga já utilizou a edição permitida após aprovação.');if(approved){next.jaFoiAprovada=true;next.edicoesAposAprovacao=edits+1;}next.aprovacao='pendente';next.ultimaEdicaoEm=new Date().toISOString();if(next.cidade!==v.cidade||next.uf!==v.uf){next.latitude=null;next.longitude=null;}}}
      next.destaque=dest;next.contratacaoUrgente=urg;next.urgente=urg;next.confidencial=conf;if(!urg)next.urgenteAte='';else if(!yes(v.contratacaoUrgente||v.urgente))next.urgenteAte=new Date(Date.now()+7*86400000).toISOString();
      next.atualizadoEm=new Date().toISOString();vs[i]=next;
      if(typeof window.salvarVagasPortal!=='function')throw Error('Não foi possível salvar a vaga.');window.salvarVagasPortal(vs);
      closeSettings();render();invoke('mostrarToast',['Alterações da vaga salvas.']);
    }catch(err){d.querySelector('#settings-feedback').textContent=err.message;}
  }

  function onClick(event) {var b=event.target.closest('[data-action]');if(!b||b.disabled)return;var a=b.dataset.action;if(a==='job-settings'){openSettings(b.dataset.id,b);}else if(a==='settings-cancel'){closeSettings();}else if(a==='settings-edit'){var fields=root.getElementById('settings-fields');fields.hidden=!fields.hidden;}else if(a==='settings-full-edit'){var editing=modalJobId;closeSettings();invoke('editarVagaEmpresa',[editing]);}else if(a==='settings-lifecycle'){modalOp=b.dataset.op;root.getElementById('settings-feedback').textContent=modalOp==='close'?'O encerramento é definitivo. Confirme em Salvar alterações.':modalOp==='pause'?'A vaga será pausada ao salvar.':'A vaga será retomada ao salvar, pelo prazo restante.';}else if(a==='settings-save'){saveSettings();}else if(a==='clear-job-filters'){query='';locationFilter='';areaFilter='';statusFilter='all';pageNumber=1;render();}else if(a==='job-filter'){statusFilter=b.dataset.filter;pageNumber=1;render();}else if(a==='nav')navigate(b.dataset.view,b.dataset.filter);else if(a==='copy-company-link'){navigator.clipboard.writeText(b.dataset.url).then(function(){b.textContent='Link copiado';}).catch(function(){var field=document.createElement('input');field.value=b.dataset.url;field.readOnly=true;field.setAttribute('aria-label','Link de teste da empresa');b.parentElement.appendChild(field);field.focus();field.select();});}else if(a==='publish')invoke('irPara',['publicar']);else if(a==='manage')manage(b.dataset.id);else if(a==='edit')invoke(typeof window.editarVagaEmpresa==='function'?'editarVagaEmpresa':'editarVaga',[b.dataset.id]);else if(a==='job')invoke(typeof window.abrirVaga==='function'?'abrirVaga':'abrirDetalheVaga',[b.dataset.id]);else if(a==='close'){invoke(typeof window.encerrarVagaEmpresa==='function'?'encerrarVagaEmpresa':'encerrarVaga',[b.dataset.id]);mount();}else if(a==='all-plans')invoke('irPara',['planos']);else if(a==='prev'||a==='next'){pageNumber+=a==='next'?1:-1;render();}else if(a==='refresh')render();}
  function render() {if(!root)return;var e=company(),vs=jobs(),cs=applications(vs);root.innerHTML=shell(view==='jobs'?jobsView(vs,cs):view==='plans'?plansView(e,vs):view==='interviews'?interviewsView(vs,cs):overview(e,vs,cs),e);}
  function mount() {var page=document.getElementById('pagina-painel-empresa');if(!page)return;var existing=document.getElementById('emRecruiterPanel');if(existing&&existing.parentNode===page){host=existing;root=host.shadowRoot;if(page.children.length!==1)page.replaceChildren(host);render();return;}host=document.createElement('div');host.id='emRecruiterPanel';host.style.cssText='display:block!important;width:100%!important;max-width:none!important;margin:0!important;padding:0!important;';root=host.attachShadow({mode:'open'});page.replaceChildren(host);root.addEventListener('click',onClick);root.addEventListener('input',function(ev){if(ev.target.id==='search'){query=ev.target.value;pageNumber=1;var e=company(),vs=jobs(),cs=applications(vs);var tmp=document.createElement('div');tmp.innerHTML=jobsView(vs,cs);root.getElementById('job-results').innerHTML=tmp.querySelector('#job-results').innerHTML;}});root.addEventListener('change',function(ev){if(ev.target.id==='job-location'||ev.target.id==='job-area'){if(ev.target.id==='job-location')locationFilter=ev.target.value;else areaFilter=ev.target.value;pageNumber=1;render();}else if(ev.target.id==='status'){statusFilter=ev.target.value;pageNumber=1;render();}});render();}
  function activate() {window.montarPainelReferenciaRecrutadorEM=mount;window.renderizarPainelEmpresa=mount;window.montarCentralRecrutadorEM=mount;window.EmpregaMaisPainelV228=mount;window.abrirCentralPlanosEmpresaV82=function(){view='plans';mount();};window.abrirGerenciarPlanoEmpresaV81=window.abrirCentralPlanosEmpresaV82;window.ativarAbaVagasRefEM=function(s){view='jobs';statusFilter=s==='pendentes'?'pending':s==='encerradas'?'closed':'active';mount();};var page=document.getElementById('pagina-painel-empresa');if(!page)return;var style=document.createElement('style');style.id='em-recruiter-host-layout';style.textContent='body:has(#pagina-painel-empresa.ativa)>header nav,body:has(#pagina-painel-empresa.ativa) #acoesPublicas,body:has(#pagina-painel-empresa.ativa) #contaCandidatoTopo,body:has(#pagina-painel-empresa.ativa) header .header-nav,body:has(#pagina-painel-empresa.ativa) .rodape{display:none!important}body:has(#pagina-painel-empresa.ativa) .topo-inner{max-width:none!important;padding-left:28px!important;padding-right:28px!important}#pagina-painel-empresa:has(>#emRecruiterPanel){padding:0!important;margin:0!important;width:100%!important;max-width:none!important;background:#f5f8fc!important}#pagina-painel-empresa:has(>#emRecruiterPanel)>:not(#emRecruiterPanel){display:none!important}';document.head.appendChild(style);mount();new MutationObserver(function(){if(page.children.length!==1||page.firstElementChild!==host)mount();}).observe(page,{childList:true});var prev=window.irPara;window.irPara=function(p){if(p==='painel-empresa'){view='overview';mount();}return prev.apply(this,arguments);};window.addEventListener('storage',render);document.addEventListener('empregamais:empresa-sincronizada',render);}
  window.montarPainelReferenciaRecrutadorEM=mount;
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',activate);else activate();
  window.addEventListener('load',function(){window.montarPainelReferenciaRecrutadorEM=mount;window.renderizarPainelEmpresa=mount;window.montarCentralRecrutadorEM=mount;mount();});
